/* ============ competitions: calendar ============ */
function pageCompetitions(params){const view=params.view||'upcoming';let list=DB.comps.filter(c=>c.status!=='draft'&&c.status!=='submitted'||canManageComp(c)||can('comp.approve'));
 if(params.type)list=list.filter(c=>c.type===params.type);if(params.level)list=list.filter(c=>c.level===params.level);if(params.region)list=list.filter(c=>c.region===params.region);
 if(view==='upcoming')list=list.filter(c=>c.end>=TODAY).sort((a,b)=>a.start<b.start?-1:1);else if(view==='results')list=list.filter(c=>c.end<TODAY||c.status==='published').sort((a,b)=>a.start<b.start?1:-1);else if(view==='mine')list=list.filter(canManageComp).sort((a,b)=>a.start<b.start?1:-1);else list=list.slice().sort((a,b)=>a.start<b.start?-1:1);
 const months={};list.forEach(c=>(months[c.start.slice(0,7)]=months[c.start.slice(0,7)]||[]).push(c));
 const sel=(k,opts,all)=>`<select aria-label="${esc(all)}" onchange="setParams({${k}:this.value})"><option value="">${esc(all)}</option>${opts.map(([v,l])=>`<option value="${v}" ${params[k]===v?'selected':''}>${esc(l)}</option>`).join('')}</select>`;
 const toApprove=DB.comps.filter(c=>c.status==='submitted'&&can('comp.approve')&&(ME.scope.kind==='all'||c.region===ME.scope.value));
 const grid=()=>{const m=params.m||TODAY.slice(0,7),[y,mo]=m.split('-').map(Number),first=`${m}-01`,dow=(new Date(first+'T00:00:00Z').getUTCDay()+6)%7,start=D.add(first,-dow);const prev=D.add(first,-1).slice(0,7),next=D.add(first,32).slice(0,7);
  return `<div class="panel"><div class="hd"><button class="btn sm" onclick="setParams({m:'${prev}'})" aria-label="prev">${ic('chevron-left')}</button><h2 style="min-width:150px;text-align:center">${D.month(first)}</h2><button class="btn sm" onclick="setParams({m:'${next}'})" aria-label="next">${ic('chevron-right')}</button><div class="r legend"><span><i style="background:var(--ink)"></i>National</span><span><i style="background:var(--blue-tint);border:1px solid var(--blue)"></i>${tr('Régional','Regional')}</span><span><i style="background:var(--accent-tint);border:1px solid var(--accent)"></i>Club</span></div></div><div class="cal">${(LANG!=='en'?['Lun','Mar','Mer','Jeu','Ven','Sam','Dim']:['Mon','Tue','Wed','Thu','Fri','Sat','Sun']).map(d=>`<div class="dow">${d}</div>`).join('')}${Array.from({length:42},(_,i)=>{const d=D.add(start,i);const evs=DB.comps.filter(c=>c.start<=d&&c.end>=d&&c.status!=='draft');return `<div class="day ${d.slice(0,7)!==m?'out':''} ${d===TODAY?'today':''}"><span class="dn">${+d.slice(8)}</span>${evs.map(c=>`<a class="cev l-${c.level.slice(0,3)}" href="#/competitions/${c.id}" title="${esc(c.name)}">${esc(c.name)}</a>`).join('')}</div>`}).join('')}</div></div>`};
 return `<div class="head"><div><h1>${tr('Calendrier des compétitions','Competition calendar')}</h1></div><div class="actions">${can('comp.create')?`<a class="btn pri" href="#/competitions/new">${ic('calendar-plus')} ${tr('Créer un événement','Create an event')}</a>`:''}</div></div>
 ${toApprove.length?`<div class="note info" style="margin-bottom:16px">${ic('calendar-check')}<div><b>${toApprove.length} ${tr('compétition(s) en attente d’inscription au calendrier','competition(s) awaiting calendar registration')}</b>${toApprove.map(c=>`<div class="sm"><a href="#/competitions/${c.id}" style="text-decoration:underline">${esc(c.name)}</a> — ${esc(CLUB(c.organiserClubId)?.name||'FEDESA')} · ${D.fmt(c.start)}</div>`).join('')}</div></div>`:''}
 <div class="row" style="justify-content:space-between;margin-bottom:6px"><div class="seg" style="padding:4px;border-radius:12px">${[['upcoming',tr('En ce moment & à venir','Now & upcoming')],['results',tr('Résultats','Results')],...(can('comp.create')?[['mine',tr('Mes événements','My events')]]:[]),['grid',tr('Vue mensuelle','Month view')]].map(([k,l])=>`<button style="height:36px;padding:0 16px;font-size:14px" class="${view===k?'on':''}" onclick="setParams({view:'${k}'})">${esc(l)}</button>`).join('')}</div>
 <div class="filters">${sel('type',Object.entries(CTYPES).map(([k,v])=>[k,tr(...v)]),'Type')}${sel('level',Object.entries(LEVELS).map(([k,v])=>[k,tr(...v)]),tr('Niveau','Level'))}${sel('region',REGIONS.map(r=>[r.code,r.name]),tr('Ligue','League'))}</div></div>
 ${view==='grid'?grid():list.length?`<div class="flat">${Object.entries(months).map(([m,cs])=>`<div class="mchip">${D.month(m+'-01')}</div><div class="tblw"><table><thead><tr><th>Date</th><th>${tr('Libellé','Name')}</th><th>${tr('Lieu','Venue')}</th><th class="hide-m">Type</th><th class="hide-m">${tr('Niveau','Level')}</th><th class="hide-m">${tr('État','State')}</th><th>${tr('Fiche','Sheet')}</th><th class="hide-m">${tr('Résultats','Results')}</th></tr></thead><tbody>${cs.map(c=>`<tr class="link" data-go="competitions/${c.id}"><td class="date">${+c.start.slice(8)}${c.end!==c.start?'–'+(+c.end.slice(8)):''} ${D.month(c.start).split(' ')[0].toLowerCase()}</td><td><b>${esc(c.name)}</b></td><td>${esc(c.city)}<span class="l2">${c.region} - ${esc(regionName(c.region))}</span></td><td class="hide-m">${tr(...CTYPES[c.type])}</td><td class="hide-m">${tr(...LEVELS[c.level])}</td><td class="hide-m">${pill(COMP_STATUS,c.status)}</td><td><a class="plus" href="#/competitions/${c.id}" aria-label="${tr('Fiche','Sheet')}">${ic('plus')}</a></td><td class="hide-m">${c.status==='published'?`<a class="plus" href="#/competitions/${c.id}?tab=results" aria-label="${tr('Résultats','Results')}">${ic('plus')}</a>`:''}</td></tr>`).join('')}</tbody></table></div>`).join('')}</div>`:`<div class="panel">${empty(tr('Aucune compétition dans cette vue','No competition in this view'))}</div>`}`}

/* ============ competition: identity sheet, programme, entries, start lists, results, image bank ============ */
const evLabel=e=>`${evName(e.code,e.sex)} ${e.sex==='M'?tr('H','M'):tr('F','W')} · ${e.cat==='TC'?tr('TC','Open'):e.cat}`;
const gsrc=g=>g.src[0]==='@'?STOCK[g.src.slice(1)]:g.src;
function eligibility(p,c,e){if(p.sex!==e.sex)return tr('Sexe','Sex');if(p.status==='suspended')return tr('Licence suspendue','Licence suspended');if(!['competition','jeunes'].includes(p.type))return tr('Licence non compétition','Non-competition licence');if(!validOn(p,c.start))return tr('Pas de licence valide le jour J','No valid licence on the day');if(p.medExp<c.start)return tr('Certificat médical expiré le jour J','Medical certificate expired on the day');const cat=catOf(p.dob,D.y(c.start));if(e.cat!=='TC'&&cat!==e.cat)return tr('Catégorie ','Category ')+cat;if(e.cat==='TC'&&['U12','U14','U16'].includes(cat))return tr('Trop jeune (TC = U18 et +)','Too young (Open = U18+)');return ''}
function pageCompetition(id,params){const c=COMP(id);if(!c)return notFound();const tab=params.tab||'',mg=canManageComp(c),org=CLUB(c.organiserClubId);const base='competitions/'+c.id;
 const nA=new Set(c.entries.map(e=>e.a)).size,nC=new Set(c.entries.map(e=>P(e.a)?.clubId)).size,rs=DB.results.filter(r=>r.compId===c.id);
 const flow=[];if(mg&&c.status==='draft')flow.push(['submitted',tr('Soumettre à la fédération','Submit to the federation'),'send','pri']);if(c.status==='submitted'&&can('comp.approve')&&(ME.scope.kind==='all'||c.region===ME.scope.value))flow.push(['approved',tr('Inscrire au calendrier','Register on the calendar'),'calendar-check','pri']);
 if(mg&&c.status==='approved')flow.push(['entries_open',tr('Ouvrir les engagements','Open entries'),'door-open','pri']);if(mg&&c.status==='entries_open')flow.push(['entries_closed',tr('Clore les engagements','Close entries'),'lock','']);if((mg||can('comp.results'))&&c.status==='entries_closed')flow.push(['results',tr('Démarrer la saisie des résultats','Start entering results'),'timer','pri']);
 if(c.status==='results'&&can('comp.publish'))flow.push(['published',tr('Contrôler et publier','Check and publish'),'badge-check','pri']);
 const cover=c.gallery[0];
 const head=`<div class="cover">${cover?`<img src="${gsrc(cover)}" alt="">`:''}<div class="ov"><div class="row" style="margin-bottom:8px">${pill(COMP_STATUS,c.status)}<span class="pill plain">${tr(...LEVELS[c.level])}</span><span class="pill plain">${tr(...CTYPES[c.type])}</span></div><div class="head" style="margin:0"><div><h1>${esc(c.name)}</h1><div style="color:rgba(255,255,255,.82);margin-top:6px">${D.fmt(c.start)}${c.end!==c.start?' – '+D.fmt(c.end):''} · ${esc(c.venue)} · ${esc(c.city)} (${c.region})</div></div><div class="actions">${flow.map(([st,l,i,k])=>`<button class="btn ${k}" onclick="compAdvance('${c.id}','${st}')">${ic(i)} ${esc(l)}</button>`).join('')}</div></div></div></div>
 ${c.status==='results'&&!can('comp.publish')?`<div class="note info" style="margin-bottom:14px">${ic('info')}<span>${tr('Résultats en saisie : ils seront visibles aux bilans après contrôle par la ligue ou la fédération.','Results being entered: they reach the rankings once checked by the league or the federation.')}</span></div>`:''}
 ${tabs(base,tab,[['',tr('Fiche d’identité','Identity sheet'),'file-text'],['programme',tr('Programme','Programme'),'list-checks',[c.events.length]],['entries',tr('Engagements','Entries'),'users',c.entries.length?[c.entries.length]:null],['startlists',tr('Listes de départ','Start lists'),'rows-3'],['results',tr('Résultats','Results'),'trophy',rs.length?[rs.length]:null],['gallery',tr('Banque d’images','Image bank'),'images',c.gallery.length?[c.gallery.length]:null]])}`;
 let body='';
 if(tab===''){const hist=c.history;body=`<div class="grid g-main"><div class="stack"><div class="panel"><div class="hd"><h2>${tr('Informations','Information')}</h2>${mg&&c.status!=='published'?`<div class="r"><button class="btn sm" onclick="editComp('${c.id}')">${ic('pencil')} ${tr('Modifier','Edit')}</button></div>`:''}</div><div class="bd"><dl class="dl c3">${[[tr('Code compétition','Competition code'),c.code],[tr('Date(s)','Date(s)'),D.fmt(c.start)+(c.end!==c.start?' – '+D.fmt(c.end):'')],[tr('Stade / parcours','Stadium / course'),c.venue],[tr('Ville','City'),c.city],[tr('Ligue','League'),regionName(c.region)],['Type',tr(...CTYPES[c.type])],[tr('Niveau','Level'),tr(...LEVELS[c.level])],[tr('Organisateur','Organiser'),org?org.name:'FEDESA — '+tr('Direction technique nationale','National technical directorate')],[tr('Directeur de réunion','Meeting director'),c.officials.director],[tr('Juge-arbitre','Referee'),c.officials.referee],[tr('Chronométrage','Timing'),c.officials.timing==='electronic'?tr('Électrique (photo-finish)','Electronic (photo finish)'):tr('Manuel','Hand timing')],[tr('Clôture des engagements','Entry deadline'),D.fmt(c.entryDeadline)],[tr('Droit d’engagement','Entry fee'),fcfa(c.fee)+' / '+tr('épreuve','event')],[tr('Téléphone','Phone'),c.contact.phone],['Email',c.contact.email]].map(([k,v])=>`<div><dt>${esc(k)}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl>${c.description?`<p style="margin-top:16px;max-width:70ch">${esc(c.description)}</p>`:''}</div></div>
  ${c.gallery.length?`<div class="panel"><div class="hd"><h2>${tr('Banque d’images','Image bank')}</h2><div class="r"><a class="btn ghost sm" href="#/${base}?tab=gallery">${tr('Tout voir','View all')} ${ic('arrow-right')}</a></div></div><div class="bd"><div class="gal">${c.gallery.slice(0,3).map((g,i)=>galFig(c,g,i)).join('')}</div></div></div>`:''}</div>
  <div class="stack"><div class="grid g2" style="gap:10px">${kpi(tr('Athlètes','Athletes'),nA,'','users')}${kpi('Clubs',nC,'','building-2')}${kpi(tr('Épreuves','Events'),c.events.length,'','list-checks')}${kpi(tr('Performances','Marks'),rs.length,'','timer')}</div>
  <div class="panel"><div class="hd"><h2>${tr('Traçabilité','Traceability')}</h2></div><div class="bd"><div class="tl">${[[tr('Créée par','Created by'),org?org.name:'FEDESA','ok'],[tr('Inscrite au calendrier par','Registered on the calendar by'),['draft','submitted'].includes(c.status)?null:(hist.find(h=>h.st==='approved')?uname(hist.find(h=>h.st==='approved').who):tr('Ligue de ','League of ')+regionName(c.region)),'ok'],[tr('Résultats chargés par','Results uploaded by'),rs.length?(hist.find(h=>h.st==='results')?uname(hist.find(h=>h.st==='results').who):c.officials.director):null,'ok'],[tr('Puis contrôlés par','Then checked by'),c.status==='published'?(hist.find(h=>h.st==='published')?uname(hist.find(h=>h.st==='published').who):c.officials.referee):null,'ok']].map(([k,v,cl])=>`<div class="ev ${v?cl:''}"><b>${esc(k)}</b><div class="t">${v?esc(v):tr('en attente','pending')}</div></div>`).join('')}</div></div></div></div></div>`}
 if(tab==='programme')body=`<div class="row" style="justify-content:space-between;margin-bottom:8px"><span class="muted sm">${tr('Épreuves × catégories, avec horaires. TC = toutes catégories à partir de U18.','Events × categories, with times. Open = all categories from U18.')}</span>${mg&&!['published','results'].includes(c.status)?`<button class="btn pri sm" onclick="addCompEvent('${c.id}')">${ic('plus')} ${tr('Ajouter une épreuve','Add an event')}</button>`:''}</div>${c.events.length?`<div class="flat"><div class="tblw"><table><thead><tr><th>${tr('Horaire','Time')}</th><th>${tr('Épreuve','Event')}</th><th>${tr('Sexe','Sex')}</th><th>${tr('Catégorie','Category')}</th><th class="hide-m">${tr('Tour','Round')}</th><th class="num">${tr('Engagés','Entered')}</th><th></th></tr></thead><tbody>${c.events.slice().sort((a,b)=>a.time<b.time?-1:1).map(e=>`<tr class="link" data-go="${base}?tab=${rs.length?'results':'entries'}&ev=${e.id}"><td class="date mono">${e.time}</td><td><b>${esc(evName(e.code,e.sex))}</b></td><td>${e.sex==='M'?tr('Hommes','Men'):tr('Femmes','Women')}</td><td>${e.cat==='TC'?tr('Toutes catégories','Open'):catLabel(e.cat)}</td><td class="hide-m">${tr('Finale directe','Straight final')}</td><td class="num">${c.entries.filter(x=>x.evId===e.id).length}</td><td style="text-align:right">${mg&&!c.entries.some(x=>x.evId===e.id)&&!['published','results'].includes(c.status)?`<button class="btn ghost sm danger" onclick="event.stopPropagation();delCompEvent('${c.id}','${e.id}')" aria-label="${tr('Retirer','Remove')}">${ic('trash-2')}</button>`:''}</td></tr>`).join('')}</tbody></table></div></div>`:`<div class="panel">${empty(tr('Programme vide','Empty programme'),c.type!=='stade'?tr('Les épreuves de cross et de route se gèrent par course (à venir).','Cross-country and road events are managed per race (coming).'):tr('Ajoutez les épreuves de la réunion.','Add the events of the meeting.'))}</div>`}`;
 if(tab==='entries'){const open=c.status==='entries_open',canEnter=can('comp.entries')&&open;const ev=params.ev||'';const list=c.entries.filter(e=>(!ev||e.evId===ev)&&(ME.role!=='club'||true));
  body=`<div class="row" style="justify-content:space-between;margin-bottom:8px"><div class="filters"><select aria-label="${tr('Épreuve','Event')}" onchange="setParams({ev:this.value})"><option value="">${tr('Toutes les épreuves','All events')}</option>${c.events.map(e=>`<option value="${e.id}" ${ev===e.id?'selected':''}>${esc(evLabel(e))}</option>`).join('')}</select><span class="sm muted">${open?`${tr('Engagements ouverts jusqu’au','Entries open until')} ${D.fmt(c.entryDeadline)}`:tr('Engagements fermés','Entries closed')}</span></div>${canEnter?`<button class="btn pri sm" onclick="addEntries('${c.id}','${ev}')">${ic('user-plus')} ${tr('Engager des athlètes','Enter athletes')}</button>`:''}</div>
  ${list.length?`<div class="flat"><div class="tblw"><table><thead><tr><th>${tr('Dossard','Bib')}</th><th>${tr('Athlète','Athlete')}</th><th class="hide-m">Club</th><th>${tr('Épreuve','Event')}</th><th class="hide-m">${tr('Perf. d’engagement','Entry mark')}</th><th class="hide-m">${tr('Licence','Licence')}</th><th></th></tr></thead><tbody>${list.map(e=>{const p=P(e.a),x=c.events.find(k=>k.id===e.evId),b=bestOf(p.id,x.code);return `<tr><td class="date mono">${e.bib??'—'}</td><td><a href="#/licensees/${p.id}"><b>${esc(p.last.toUpperCase())} ${esc(p.first)}</b></a>${mineMark(p)}<span class="l2 mono" style="color:var(--ink-2)">${p.no} · ${catOf(p.dob)}${p.sex}</span></td><td class="hide-m">${esc(CLUB(p.clubId).name)}</td><td>${esc(evLabel(x))}</td><td class="hide-m"><span class="perf">${b?fmtPerf(x.code,b.perf):'—'}</span></td><td class="hide-m">${validOn(p,c.start)?`<span class="pill ok">${tr('Valide le jour J','Valid on the day')}</span>`:`<span class="pill crit">${tr('À renouveler','To renew')}</span>`}</td><td style="text-align:right">${canEnter&&inScope(p)?`<button class="btn ghost sm danger" onclick="delEntry('${c.id}','${e.id}')" aria-label="${tr('Retirer','Remove')}">${ic('x')}</button>`:''}</td></tr>`}).join('')}</tbody></table></div></div>`:`<div class="panel">${empty(tr('Aucun engagement','No entry yet'),open?tr('Les clubs engagent leurs athlètes : licence, catégorie et certificat médical sont vérifiés automatiquement.','Clubs enter their athletes: licence, category and medical certificate are checked automatically.'):'')}</div>`}`}
 if(tab==='startlists'){const evs=c.events.filter(e=>c.entries.some(x=>x.evId===e.id));const ev=evs.find(e=>e.id===params.ev)||evs[0];
  body=!ev?`<div class="panel">${empty(tr('Pas encore de liste de départ','No start list yet'),tr('Elles se composent automatiquement à partir des engagements.','They are built automatically from the entries.'))}</div>`:`<div class="row" style="justify-content:space-between;margin-bottom:12px"><div class="filters"><select aria-label="${tr('Épreuve','Event')}" onchange="setParams({ev:this.value})">${evs.map(e=>`<option value="${e.id}" ${ev.id===e.id?'selected':''}>${esc(evLabel(e))} — ${e.time}</option>`).join('')}</select></div><span class="sm muted">${ic('wand-sparkles')} ${tr('Séries composées en serpentin sur la performance d’engagement ; meilleurs temps aux couloirs 4‑5‑3‑6.','Heats seeded serpentine-style on entry marks; best marks in lanes 4‑5‑3‑6.')}</span></div><div class="grid g2">${heats(c,ev).map((h,i)=>`<div class="panel"><div class="hd"><h2>${EV(ev.code).kind==='t'?(tr('Série','Heat')+' '+(i+1)):tr('Ordre de passage','Order of competition')}</h2><span class="muted sm">${h.length} ${tr('athlètes','athletes')}</span></div><div class="bd" style="padding-block:6px">${h.map(x=>`<div class="lane" style="grid-template-columns:34px minmax(0,1fr) auto"><span class="ln">${x.lane}</span><span style="min-width:0"><b style="font-weight:600">${esc(fullName(x.p))}</b><span class="sm muted" style="display:block;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${esc(CLUB(x.p.clubId).name)} · ${tr('dossard','bib')} ${x.bib??'—'}</span></span><span class="perf mono">${x.seed?fmtPerf(ev.code,x.seed):'—'}</span></div>`).join('')}</div></div>`).join('')}</div>`}
 if(tab==='results')body=compResults(c,params,mg);
 if(tab==='gallery')body=`<div class="row" style="justify-content:space-between;margin-bottom:12px"><span class="muted sm" style="max-width:70ch">${tr('Photos officielles de l’événement, accessibles aux clubs, aux athlètes et à la presse. Chaque image porte son crédit et son droit d’usage.','Official photos of the event, open to clubs, athletes and the press. Every picture carries its credit and usage rights.')}</span><span class="pill plain">${c.gallery.length} ${tr('images','images')} · ${c.gallery.filter(g=>g.press).length} ${tr('libres presse','press-cleared')}</span></div><div class="gal">${c.gallery.map((g,i)=>galFig(c,g,i)).join('')}${mg||can('comp.publish')?`<label class="gal-add"><figure class="add" style="aspect-ratio:3/2;margin:0;border-radius:14px"><span>${ic('image-plus')}<br>${tr('Ajouter des images','Add images')}<br><span class="xs">JPG · PNG · AVIF — 900 Ko max</span></span><input type="file" accept="image/*" multiple aria-label="${tr('Ajouter des images','Add images')}" onchange="galAdd('${c.id}',this)"></figure></label>`:''}</div>${!c.gallery.length&&!mg?`<div class="panel" style="margin-top:12px">${empty(tr('Pas encore d’image','No image yet'))}</div>`:''}`;
 return shellCrumbs([[tr('Compétitions','Competitions'),'competitions'],[c.name]],head+body)}
const galFig=(c,g,i)=>`<figure tabindex="0" onclick="lightbox('${c.id}',${i})" onkeydown="if(event.key==='Enter')lightbox('${c.id}',${i})"><img src="${gsrc(g)}" alt="${esc(tr(g.fr,g.en||g.fr))}" loading="lazy">${g.press?`<span class="pill ok press plain">${tr('Libre presse','Press-cleared')}</span>`:''}<figcaption>${esc(tr(g.fr,g.en||g.fr))}<br><span style="opacity:.7">© ${esc(g.credit)}</span></figcaption></figure>`;
function lightbox(cid,i){const c=COMP(cid),n=c.gallery.length;i=(i+n)%n;const g=c.gallery[i],mg=canManageComp(c);let lb=$('#lb');if(!lb){lb=document.createElement('div');lb.id='lb';document.body.appendChild(lb)}
 lb.innerHTML=`<div class="lightbox" onclick="if(event.target===this)closeLb()"><div><img src="${gsrc(g)}" alt=""><div class="cap">${esc(tr(g.fr,g.en||g.fr))}<span>© ${esc(g.credit)} · ${g.press?tr('usage presse autorisé','press use allowed'):tr('usage interne fédération et clubs','federation and club use only')} · ${i+1}/${n}</span><div class="row" style="justify-content:center;margin-top:10px"><button class="btn sm" onclick="toast('${tr('Téléchargement HD : actif en production','HD download: enabled in production')}','download')">${ic('download')} ${tr('Télécharger HD','Download HD')}</button>${mg?`<button class="btn sm" onclick="galEdit('${cid}',${i})">${ic('pencil')} ${tr('Légende & droits','Caption & rights')}</button><button class="btn sm danger" onclick="galDel('${cid}',${i})">${ic('trash-2')}</button>`:''}</div></div></div>${n>1?`<button class="nav" style="left:16px" onclick="lightbox('${cid}',${i-1})" aria-label="prev">${ic('chevron-left')}</button><button class="nav" style="right:16px" onclick="lightbox('${cid}',${i+1})" aria-label="next">${ic('chevron-right')}</button>`:''}<button class="nav" style="top:34px;right:16px" onclick="closeLb()" aria-label="${tr('Fermer','Close')}">${ic('x')}</button></div>`;icons()}
function closeLb(){const l=$('#lb');if(l)l.innerHTML=''}
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeLb()});
function galAdd(cid,input){const c=COMP(cid);let n=0;[...input.files].slice(0,8).forEach(f=>{if(!f.type.startsWith('image/')||f.size>900*1024){toast(f.name+' — '+tr('ignorée (900 Ko max)','skipped (900 KB max)'),'alert-triangle');return}const r=new FileReader();r.onload=()=>{c.gallery.push({id:uid(),src:r.result,fr:f.name.replace(/\.\w+$/,''),en:'',credit:ME.name,press:false,by:ME.id,ts:nowISO()});save();render({keepScroll:true})};r.readAsDataURL(f);n++});if(n){log('Images ajoutées à la banque','competitions',c.name,null,{count:n});toast(n+' '+tr('image(s) ajoutée(s)','image(s) added'),'image-plus')}}
function galEdit(cid,i){closeLb();const g=COMP(cid).gallery[i];modal(tr('Légende & droits','Caption & rights'),`<div class="form">${field('g-fr',tr('Légende (FR)','Caption (FR)'),g.fr,{full:1})}${field('g-en',tr('Légende (EN)','Caption (EN)'),g.en||'',{full:1})}${field('g-cr',tr('Crédit photo','Photo credit'),g.credit)}<label class="chk" style="align-self:end;padding-bottom:9px"><input type="checkbox" id="g-pr" ${g.press?'checked':''}> ${tr('Usage presse autorisé','Press use allowed')}</label></div>`,()=>{g.fr=val('g-fr');g.en=val('g-en');g.credit=val('g-cr');g.press=$('#g-pr').checked})}
function galDel(cid,i){if(!confirmSoft(tr('Supprimer cette image ?','Delete this image?')))return;COMP(cid).gallery.splice(i,1);closeLb();save();render({keepScroll:true})}
function heats(c,ev){const lb=lowerBetter(ev.code);const list=c.entries.filter(x=>x.evId===ev.id).map(x=>{const p=P(x.a),b=bestOf(p.id,ev.code);return {p,bib:x.bib,seed:b?.perf??null}}).sort((a,b)=>a.seed==null?1:b.seed==null?-1:lb?a.seed-b.seed:b.seed-a.seed);
 if(EV(ev.code).kind!=='t'||['800','1500','5000','10000','3000SC'].includes(ev.code))return [list.slice().reverse().map((x,i)=>({...x,lane:i+1}))];
 const n=Math.ceil(list.length/8),hs=Array.from({length:n},()=>[]);list.forEach((x,i)=>{const r=Math.floor(i/n),k=i%n;hs[r%2?n-1-k:k].push(x)});const order=[4,5,3,6,2,7,1,8];return hs.map(h=>h.map((x,i)=>({...x,lane:order[i]})).sort((a,b)=>a.lane-b.lane))}
function compAdvance(id,st){const c=COMP(id);if(st==='published'){const n=DB.results.filter(r=>r.compId===id).length;if(!n){toast(tr('Aucun résultat à publier','No result to publish'),'alert-triangle');return}}const before=c.status;c.status=st;c.history.push({ts:nowISO(),who:ME.id,st});log('Compétition : '+COMP_STATUS[st][0],'competitions',c.name,{status:before},{status:st});save();render({keepScroll:true});toast(tr(...COMP_STATUS[st]),st==='published'?'badge-check':'check-circle-2')}
function compForm(c){return `<div class="form">${field('c-name',tr('Nom de la compétition','Competition name'),c.name||'',{req:1,full:1,ph:tr('Ex. : Meeting de la Petite Côte','E.g. Petite Côte Meeting')})}${field('c-start',tr('Date de début','Start date'),c.start||'',{type:'date',req:1,attr:`min="${TODAY}"`})}${field('c-end',tr('Date de fin','End date'),c.end||'',{type:'date'})}${field('c-type','Type',c.type||'stade',{options:Object.entries(CTYPES).map(([k,v])=>[k,tr(...v)])})}${field('c-level',tr('Niveau','Level'),c.level||'club',{options:Object.entries(LEVELS).filter(([k])=>k!=='international'||ME.role==='superadmin').map(([k,v])=>[k,tr(...v)])})}${field('c-region',tr('Ligue','League'),c.region||CLUB(ME.scope.value)?.region||ME.scope.value||'DK',{options:REGIONS.map(r=>[r.code,r.name])})}${field('c-city',tr('Ville','City'),c.city||CLUB(ME.scope.value)?.city||'',{req:1,attr:'list="dl-cities2"'})}${field('c-venue',tr('Stade / parcours','Stadium / course'),c.venue||'',{ph:'Stade Iba Mar Diop'})}${field('c-deadline',tr('Clôture des engagements','Entry deadline'),c.entryDeadline||'',{type:'date'})}${field('c-dir',tr('Directeur de réunion','Meeting director'),c.officials?.director||ME.name)}${field('c-ref',tr('Juge-arbitre','Referee'),c.officials?.referee||'')}${field('c-timing',tr('Chronométrage','Timing'),c.officials?.timing||'electronic',{options:[['electronic',tr('Électrique (photo-finish)','Electronic (photo finish)')],['manual',tr('Manuel','Hand timing')]]})}${field('c-fee',tr('Droit d’engagement (FCFA / épreuve)','Entry fee (FCFA / event)'),c.fee??500,{type:'number'})}${field('c-desc',tr('Présentation','Description'),c.description||'',{area:1,full:1})}</div><datalist id="dl-cities2">${Object.values(CITIES).flat().map(x=>`<option value="${esc(x)}">`).join('')}</datalist>`}
function compRead(c){const name=val('c-name'),start=val('c-start'),city=val('c-city');if(!name||!start||!city){toast(tr('Nom, date et ville sont obligatoires','Name, date and city are required'),'alert-triangle');return false}Object.assign(c,{name,start,end:val('c-end')||start,type:val('c-type'),level:val('c-level'),region:val('c-region'),city,venue:val('c-venue')||VENUES[val('c-region')],entryDeadline:val('c-deadline')||D.add(start,-7),fee:+val('c-fee')||0,description:val('c-desc')});c.officials={director:val('c-dir'),referee:val('c-ref'),timing:val('c-timing')};if(c.end<c.start)c.end=c.start;return true}
function editComp(id){const c=COMP(id);modal(tr('Modifier la fiche','Edit the sheet'),compForm(c),()=>{if(!compRead(c))return false;log('Fiche compétition modifiée','competitions',c.name)},null,{wide:1})}
function pageCompNew(){if(!can('comp.create'))return notFound();const std=['100','200','400','800','1500','HH','LJ','TJ','SP','JT'];
 return shellCrumbs([[tr('Compétitions','Competitions'),'competitions'],[tr('Créer un événement','Create an event')]],`<div class="head"><div><h1>${tr('Créer un événement','Create an event')}</h1><div class="sub">${tr('La compétition est créée en brouillon, puis soumise à la ligue ou à la fédération pour inscription au calendrier officiel.','The competition is created as a draft, then submitted to the league or the federation for registration on the official calendar.')}</div></div></div>
 <div class="grid g-main"><div class="panel"><div class="hd"><h2>${tr('Fiche d’identité','Identity sheet')}</h2></div><div class="bd">${compForm({})}</div></div>
 <div class="stack"><div class="panel"><div class="hd"><h2>${tr('Programme','Programme')}</h2></div><div class="bd stack" style="gap:12px"><p class="sm muted">${tr('Cochez les épreuves ; chacune est créée pour les femmes et les hommes. Vous affinerez horaires et catégories ensuite.','Tick the events; each is created for women and men. Refine times and categories afterwards.')}</p><div class="row" style="gap:6px">${EVENTS.map(e=>`<label class="pill plain" style="height:28px;cursor:pointer"><input type="checkbox" name="cev" value="${e.code}" ${std.includes(e.code)?'checked':''} style="accent-color:var(--accent)"> ${esc(tr(e.fr,e.en))}</label>`).join('')}</div>${field('c-cat',tr('Catégorie','Category'),'TC',{options:[['TC',tr('Toutes catégories (U18 et +)','Open (U18+)')],...CATS.filter(k=>k.code!=='MAS').map(k=>[k.code,`${k.code} · ${tr(k.fr,k.en)}`])]})}${field('c-first',tr('Première épreuve à','First event at'),'15:00',{type:'time'})}</div></div>
 <button class="btn pri" style="height:44px" onclick="createComp()">${ic('calendar-plus')} ${tr('Créer le brouillon','Create the draft')}</button></div></div>`)}
function createComp(){const c={id:'k'+uid(),code:String(261040+DB.comps.length*7),entries:[],events:[],gallery:[],history:[],status:'draft',organiserClubId:ME.scope.kind==='club'?ME.scope.value:null,contact:{phone:CLUB(ME.scope.value)?.phone||'+221 33 821 00 00',email:ME.email}};if(!compRead(c))return;
 if(c.type==='stade'){let [h,m]=(val('c-first')||'15:00').split(':').map(Number),t=h*60+m;const cat=val('c-cat');$$('input[name=cev]:checked').forEach(i=>['F','M'].forEach(sex=>{c.events.push({id:c.id+'-'+i.value+sex,code:i.value,sex,cat,time:`${String(Math.floor(t/60)).padStart(2,'0')}:${String(t%60).padStart(2,'0')}`,round:'F'});t+=12}))}
 DB.comps.push(c);log('Compétition créée','competitions',c.name);save();toast(tr('Brouillon créé','Draft created'),'calendar-plus');go('competitions/'+c.id+'?tab=programme')}
function addCompEvent(id){const c=COMP(id);modal(tr('Ajouter une épreuve','Add an event'),`<div class="form">${field('ae-code',tr('Épreuve','Event'),'100',{options:EVENTS.map(e=>[e.code,tr(e.fr,e.en)])})}${field('ae-sex',tr('Sexe','Sex'),'F',{options:[['F',tr('Femmes','Women')],['M',tr('Hommes','Men')]]})}${field('ae-cat',tr('Catégorie','Category'),'TC',{options:[['TC',tr('Toutes catégories','Open')],...CATS.map(k=>[k.code,k.code+' · '+tr(k.fr,k.en)])]})}${field('ae-time',tr('Horaire','Time'),'16:00',{type:'time'})}</div>`,()=>{const code=val('ae-code'),sex=val('ae-sex'),cat=val('ae-cat'),eid=c.id+'-'+code+sex+(cat==='TC'?'':cat);if(c.events.some(e=>e.id===eid)){toast(tr('Épreuve déjà au programme','Event already on the programme'),'alert-triangle');return false}c.events.push({id:eid,code,sex,cat,time:val('ae-time'),round:'F'})},tr('Ajouter','Add'))}
function delCompEvent(id,eid){const c=COMP(id);c.events=c.events.filter(e=>e.id!==eid);save();render({keepScroll:true})}
function addEntries(id,evId){const c=COMP(id);const draw=()=>{const e=c.events.find(x=>x.id===($('#en-ev')?.value||evId))||c.events[0],q=($('#en-q')?.value||'').toLowerCase();const pool=myPeople().filter(p=>p.events.length&&p.sex===e.sex&&(!q||fullName(p).toLowerCase().includes(q)||p.no.toLowerCase().includes(q))).map(p=>({p,why:eligibility(p,c,e),in:c.entries.some(x=>x.evId===e.id&&x.a===p.id),b:bestOf(p.id,e.code)})).sort((a,b)=>(!!a.why-!!b.why)||((b.p.events.includes(e.code))-(a.p.events.includes(e.code)))||a.p.last.localeCompare(b.p.last)).slice(0,40);
  $('#en-list').innerHTML=pool.map(({p,why,in:isIn,b})=>`<label class="doc" style="cursor:${why||isIn?'not-allowed':'pointer'};opacity:${why||isIn?.55:1}"><input type="checkbox" name="en" value="${p.id}" ${why||isIn?'disabled':''} style="width:16px;height:16px;accent-color:var(--accent)"><span class="dm"><b>${esc(p.last.toUpperCase())} ${esc(p.first)} <span class="mono xs muted">${catOf(p.dob,D.y(c.start))}${p.sex}</span></b><span>${esc(CLUB(p.clubId).name)} · ${p.no}</span></span><span class="da">${isIn?`<span class="pill ok">${tr('Déjà engagé','Already entered')}</span>`:why?`<span class="pill crit">${esc(why)}</span>`:`<span class="perf mono">${b?fmtPerf(e.code,b.perf):tr('sans perf.','no mark')}</span>`}</span></label>`).join('')||`<p class="muted sm" style="padding:16px 0">${tr('Aucun athlète trouvé','No athlete found')}</p>`};
 modal(tr('Engager des athlètes','Enter athletes'),`<div class="form" style="margin-bottom:10px">${field('en-ev',tr('Épreuve','Event'),evId||c.events[0]?.id,{options:c.events.map(e=>[e.id,evLabel(e)])})}${field('en-q',tr('Rechercher','Search'),'',{ph:tr('Nom ou n° de licence','Name or licence no.')})}</div><p class="xs muted" style="margin-bottom:4px">${tr('Contrôles automatiques : licence valide le jour J, type compétition, catégorie, certificat médical, suspension.','Automatic checks: licence valid on the day, competition type, category, medical certificate, suspension.')}</p><div id="en-list" style="max-height:44vh;overflow-y:auto;scrollbar-width:thin"></div>`,()=>{const e=c.events.find(x=>x.id===val('en-ev'));const ids=$$('input[name=en]:checked').map(i=>i.value);if(!ids.length){toast(tr('Sélectionnez au moins un athlète','Select at least one athlete'),'alert-triangle');return false}let bib=Math.max(0,...c.entries.map(x=>x.bib||0));ids.forEach(a=>{const ex=c.entries.find(x=>x.a===a);c.entries.push({id:uid(),evId:e.id,a,seed:null,bib:ex?ex.bib:++bib,status:'confirmed'})});log('Engagements','competitions',c.name,null,{event:evLabel(e),count:ids.length});toast(`${ids.length} ${tr('engagement(s) enregistré(s)','entry(ies) saved')} — ${fcfa(ids.length*c.fee)}`,'user-plus')},tr('Engager la sélection','Enter selection'),{wide:1,noFocus:1});
 draw();$('#en-ev').onchange=draw;$('#en-q').oninput=draw}
function delEntry(id,eid){const c=COMP(id);c.entries=c.entries.filter(e=>e.id!==eid);save();render({keepScroll:true})}

function compResults(c,params,mg){const evs=c.events.filter(e=>c.entries.some(x=>x.evId===e.id));if(!evs.length)return `<div class="panel">${empty(tr('Pas encore de résultats','No results yet'),c.type!=='stade'?tr('Classement de course : import du chronométreur (à venir).','Race standings: timing-company import (coming).'):'')}</div>`;
 const ev=evs.find(e=>e.id===params.ev)||evs[0],E=EV(ev.code);const rows=DB.results.filter(r=>r.compId===c.id&&r.evId===ev.id);const canEnter=c.status==='results'&&(mg||can('comp.results'));const edit=canEnter&&(params.edit==='1'||!rows.length);
 const selector=`<div class="row" style="justify-content:space-between;margin-bottom:12px"><div class="filters"><select aria-label="${tr('Épreuve','Event')}" onchange="setParams({ev:this.value,edit:''})">${evs.map(e=>{const n=DB.results.filter(r=>r.compId===c.id&&r.evId===e.id).length;return `<option value="${e.id}" ${ev.id===e.id?'selected':''}>${esc(evLabel(e))}${n?'':' — '+tr('à saisir','to enter')}</option>`}).join('')}</select><span class="sm muted mono">${ev.cat==='TC'?'TCX':ev.cat} | Chr : ${c.officials.timing==='electronic'?'E':'M'} | ${ev.time}</span></div>${canEnter&&!edit?`<button class="btn sm" onclick="setParams({edit:'1'})">${ic('pencil')} ${tr('Corriger','Correct')}</button>`:''}${c.status==='published'&&rows.length?`<button class="btn sm" onclick="exportResults('${c.id}','${ev.id}')">${ic('download')} CSV</button>`:''}</div>`;
 if(edit){const ents=heats(c,ev).flat();return selector+`<div class="panel"><div class="hd"><h2>${tr('Saisie des résultats','Results entry')} — ${esc(evLabel(ev))}</h2><span class="muted sm">${tr('Formats acceptés','Accepted formats')} : ${E.kind==='t'?"10.42 · 10''42 · 1:48.32":'7.85 · 7m85'}</span></div><div class="bd" style="padding-block:8px">${E.wind&&E.kind==='t'?`<div class="row" style="margin-bottom:8px"><label class="f" style="flex-direction:row;align-items:center;gap:8px">${tr('Vent de la course (m/s)','Race wind (m/s)')} <input id="rw-all" class="mono" style="width:90px" value="${rows[0]?.wind??''}" placeholder="+1.2" inputmode="decimal"></label></div>`:''}
  ${ents.map(x=>{const r=rows.find(k=>k.a===x.p.id);return `<div class="lane" data-a="${x.p.id}"><span class="ln">${x.lane}</span><span style="min-width:0"><b style="font-weight:600">${esc(fullName(x.p))}</b><span class="sm muted" style="display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${esc(CLUB(x.p.clubId).name)} · ${tr('RP','PB')} ${x.seed?fmtPerf(ev.code,x.seed):'—'}</span></span><input class="pf" aria-label="${tr('Performance','Mark')} ${esc(fullName(x.p))}" placeholder="${E.kind==='t'?"10''42":'7m85'}" value="${r?.perf!=null?fmtPerf(ev.code,r.perf):''}" inputmode="decimal">${E.wind&&E.kind!=='t'?`<input class="wd w" aria-label="${tr('Vent','Wind')}" placeholder="+0.8" value="${r?.wind??''}" inputmode="decimal">`:'<span class="w"></span>'}<select class="st s" aria-label="${tr('Statut','Status')}">${['OK','DNS','DNF','DQ','NM'].map(s=>`<option ${r?.st===s?'selected':''}>${s}</option>`).join('')}</select></div>`}).join('')}</div><div class="hd" style="border-top:1px solid var(--line);border-bottom:0"><span class="xs muted">DNS ${tr('non partant','did not start')} · DNF ${tr('abandon','did not finish')} · DQ ${tr('disqualifié','disqualified')} · NM ${tr('aucune marque','no mark')}</span><div class="r">${rows.length?`<button class="btn" onclick="setParams({edit:''})">${tr('Annuler','Cancel')}</button>`:''}<button class="btn pri" onclick="saveResults('${c.id}','${ev.id}')">${ic('save')} ${tr('Enregistrer et classer','Save and rank')}</button></div></div></div>`}
 const sorted=rows.slice().sort((a,b)=>(a.place??99)-(b.place??99));
 return selector+(sorted.length?`<div class="flat"><div class="tblw"><table><thead><tr><th>${tr('Place','Place')}</th><th>${tr('Résultat','Result')}</th><th>${tr('Nom','Name')}</th><th class="hide-m">Club</th><th class="hide-m">${tr('Ligue','League')}</th><th class="hide-m">${tr('Infos','Info')}</th><th class="hide-m">${tr('Niveau','Level')}</th><th class="hide-m num">Points</th></tr></thead><tbody>${sorted.map(r=>{const p=P(r.a),pts=r.st==='OK'?points(r.code,r.sex,r.perf):0;return `<tr class="link" data-go="licensees/${p.id}?tab=results"><td>${r.place?`<span class="rank r${r.place}">${r.place}</span>`:'<span class="muted">—</span>'}</td><td><span class="perf">${r.st==='OK'?fmtPerf(r.code,r.perf):r.st}</span>${r.wind!=null&&r.st==='OK'?` <span class="xs muted mono">(${windTxt(r.wind)})</span>`:''} ${flagTag(r)}</td><td><b>${esc(p.last.toUpperCase())} ${esc(p.first)}</b>${mineMark(p)}</td><td class="hide-m">${esc(CLUB(p.clubId).name)}</td><td class="hide-m">${p.region}</td><td class="hide-m mono">${catOf(p.dob)}${p.sex}/${String(D.y(p.dob)).slice(2)}</td><td class="hide-m">${pts?levelOf(pts):''}</td><td class="hide-m num">${pts||''}</td></tr>`}).join('')}</tbody></table></div></div>`:`<div class="panel">${empty(tr('Résultats non saisis','Results not entered'),canEnter?'':tr('La saisie s’ouvre une fois les engagements clos.','Entry opens once entries are closed.'))}</div>`)}
function saveResults(cid,evId){const c=COMP(cid),ev=c.events.find(e=>e.id===evId),E=EV(ev.code);const wAll=$('#rw-all')?parseFloat($('#rw-all').value.replace(',','.')):null;const rows=[];let bad=0;
 $$('.lane[data-a]').forEach(l=>{const a=l.dataset.a,st=l.querySelector('.st').value,raw=l.querySelector('.pf').value.trim();const perf=st==='OK'?parsePerf(ev.code,raw):null;if(st==='OK'&&!raw)return;if(st==='OK'&&perf==null){bad++;l.querySelector('.pf').style.borderColor='var(--red)';return}const wd=l.querySelector('.wd');const wind=E.wind?(wd?parseFloat(wd.value.replace(',','.')):wAll):null;rows.push({id:uid(),compId:cid,evId,a,code:ev.code,sex:ev.sex,perf,wind:isFinite(wind)?wind:null,st,date:c.start,place:null})});
 if(bad){toast(tr('Performance illisible : vérifiez les champs en rouge','Unreadable mark: check the fields in red'),'alert-triangle');return}if(!rows.length){toast(tr('Saisissez au moins un résultat','Enter at least one result'),'alert-triangle');return}
 rankRows(rows,ev.code);DB.results=DB.results.filter(r=>!(r.compId===cid&&r.evId===evId)).concat(rows);
 /* a legal mark better than the national record opens a ratification file instead of silently becoming the record */
 rows.filter(legal).forEach(r=>{const ref=E.ref[r.sex];if(lowerBetter(r.code)?r.perf<ref:r.perf>ref){r.nr=true;DB.records.unshift({id:uid(),rid:r.id,a:r.a,code:r.code,sex:r.sex,perf:r.perf,wind:r.wind,compId:cid,date:r.date,status:'pending',checks:{timing:c.officials.timing==='electronic',wind:r.wind!=null||!E.wind,doping:false,referee:false}})}});
 log('Résultats saisis','competitions',c.name+' — '+evLabel(ev),null,{rows:rows.length});save();RT=RT.replace(/[?&]edit=1/,'');const pbs=rows.filter(r=>ridx().flags[r.id]==='PB').length;toast(`${rows.length} ${tr('résultats classés','results ranked')}${pbs?` · ${pbs} ${tr('records personnels','personal bests')}`:''}${rows.some(r=>r.nr)?' · '+tr('RECORD NATIONAL à homologuer','NATIONAL RECORD to ratify'):''}`,'trophy');render({keepScroll:true})}
function exportResults(cid,evId){const c=COMP(cid),ev=c.events.find(e=>e.id===evId);const rows=[['place','performance','vent','statut','licence','nom','prenom','naissance','club','ligue']].concat(DB.results.filter(r=>r.compId===cid&&r.evId===evId).sort((a,b)=>(a.place??99)-(b.place??99)).map(r=>{const p=P(r.a);return [r.place??'',r.perf??'',r.wind??'',r.st,p.no,p.last,p.first,p.dob,CLUB(p.clubId).name,p.region]}));exportBox(`${c.name} — ${evLabel(ev)}`,csv(rows))}

/* ============ rankings (bilans), records, club standings ============ */
function seasonList(code,sex,o){const lb=lowerBetter(code),best={};DB.results.forEach(r=>{if(r.code!==code||r.sex!==sex||r.st!=='OK'||r.perf==null)return;if(COMP(r.compId)?.status!=='published')return;if(o.wind!=='all'&&!legal(r))return;const p=P(r.a);if(!p)return;if(o.cat&&catOf(p.dob)!==o.cat)return;if(o.region&&p.region!==o.region)return;if(o.club&&p.clubId!==o.club)return;const b=best[r.a];if(!b||(lb?r.perf<b.perf:r.perf>b.perf))best[r.a]=r});return Object.values(best).sort((a,b)=>lb?a.perf-b.perf:b.perf-a.perf)}
const NR={'100':{M:['Mamadou Fall Sarr',2025],F:['Aminata Diouf',1999]},'200':{M:['Oumar Loum',2000],F:['Aïda Diop',2000]},'400':{M:['Cheikh Tidiane Diouf',2024],F:['Amy Mbacké Thiam',2001]},'800':{M:['Moussa Fall',1988],F:['Raissa Laval',2014]},'1500':{M:['Mor Seck',2014],F:['Raissa Laval',2016]},'HH':{M:['Louis François Mendy',2023],F:['Mame Tacko Diouf',2000]},'400H':{M:['Amadou Dia Bâ',1988],F:['Mame Tacko Diouf',1999]},'HJ':{M:['Moussa Sagna Fall',1982],F:['Constance Senghor',1984]},'LJ':{M:['Cheikh Tidiane Touré',1997],F:['Kène Ndoye',2004]},'TJ':{M:['Ndiss Kaba Badji',2008],F:['Saly Sarr',2026]},'SP':{M:['Lamine Badji',1982],F:['Nafissatou Mboup',1998]},'JT':{M:['Bouna Diop',1997],F:['Florence Corréa',2010]}};
function pageRankings(params){const mode=params.mode||'';const code=params.ev||'100',sex=params.sex||'F',n=+(params.n||20);
 const sel=(k,opts,cur,all)=>`<select aria-label="${esc(k)}" onchange="setParams({${k}:this.value})">${all?`<option value="">${esc(all)}</option>`:''}${opts.map(([v,l])=>`<option value="${v}" ${String(cur)===String(v)?'selected':''}>${esc(l)}</option>`).join('')}</select>`;
 let body='';
 if(mode===''){const list=seasonList(code,sex,{cat:params.cat,region:params.region,wind:params.wind});
  body=`<div class="filters" style="margin-bottom:8px">${sel('season',[['2026',tr('Saison 2026','Season 2026')]],'2026')}${sel('ev',EVENTS.map(e=>[e.code,evName(e.code,sex)]),code)}${sel('sex',[['F',tr('Femmes','Women')],['M',tr('Hommes','Men')]],sex)}${sel('cat',CATS.map(c=>[c.code,tr(c.fr,c.en)]),params.cat,tr('Toutes catégories','All categories'))}${sel('wind',[['',tr('Vent régulier','Wind-legal')],['all',tr('Tous vents','All winds')]],params.wind||'')}${sel('region',REGIONS.map(r=>[r.code,r.name]),params.region,tr('Toutes les ligues','All leagues'))}${sel('n',[[10,'10'],[20,'20'],[50,'50'],[100,'100']],n)}</div>
  <div class="flat"><div class="mchip dark">2026 | ${esc(evName(code,sex))} | ${sex} | ${params.cat||'TC'} <span style="font-weight:500;margin-left:10px;color:#C9D6CF">${list.length} ${tr('résultats','results')}</span></div>${list.length?`<div class="tblw"><table><thead><tr><th>${tr('Place','Place')}</th><th>${tr('Performance','Mark')}</th><th>${tr('Nom','Name')}</th><th class="hide-m">Club</th><th class="hide-m">${tr('Ligue','League')}</th><th class="hide-m">${tr('Infos','Info')}</th><th class="hide-m">Points</th><th>Date</th><th class="hide-m">${tr('Lieu','Venue')}</th></tr></thead><tbody>${list.slice(0,n).map((r,i)=>{const p=P(r.a),pl=i&&list[i-1].perf===r.perf?'-':i+1;return `<tr class="link" data-go="licensees/${p.id}?tab=bilan&ev=${code}"><td>${typeof pl==='number'&&pl<=3?`<span class="rank r${pl}">${pl}</span>`:`<span class="tnum" style="padding-left:8px">${pl}</span>`}</td><td><span class="perf">${fmtPerf(code,r.perf)}</span>${r.wind!=null?` <span class="xs muted mono">(${windTxt(r.wind)})</span>`:''} ${ridx().flags[r.id]==='PB'?`<span class="tag pb">${tr('RP','PB')}</span>`:''}${r.wind>2?' <span class="tag w">w</span>':''}</td><td><b>${esc(p.last.toUpperCase())} ${esc(p.first)}</b>${p.nat!=='SEN'?` <span class="xs muted">(${p.nat})</span>`:''}${mineMark(p)}</td><td class="hide-m">${esc(CLUB(p.clubId).name)}</td><td class="hide-m">${p.region}</td><td class="hide-m mono">${catOf(p.dob)}${p.sex}/${String(D.y(p.dob)).slice(2)}</td><td class="hide-m tnum">${points(code,sex,r.perf)}</td><td class="tnum">${r.date.slice(8)}/${r.date.slice(5,7)}/${r.date.slice(2,4)}</td><td class="hide-m">${esc(COMP(r.compId).city)}</td></tr>`}).join('')}</tbody></table></div>`:`<div class="panel" style="margin-top:8px">${empty(tr('Aucune performance pour ces critères','No mark for these criteria'))}</div>`}</div>`}
 if(mode==='records'){const pend=DB.records.filter(r=>r.status==='pending');body=`${pend.length?`<div class="panel" style="margin-bottom:16px;border-color:var(--gold)"><div class="hd"><h2>${tr('Dossiers d’homologation en cours','Ratification files in progress')}</h2><span class="badge warn">${pend.length}</span></div><div class="bd stack">${pend.map(r=>{const p=P(r.a),ck=r.checks;return `<div class="row" style="justify-content:space-between"><div><b>${esc(evName(r.code,r.sex))} ${r.sex} — <span class="mono">${fmtPerf(r.code,r.perf)}</span>${r.wind!=null?` (${windTxt(r.wind)})`:''}</b> · ${esc(fullName(p))}<div class="sm muted">${esc(COMP(r.compId).name)} · ${D.fmt(r.date)}</div><div class="row" style="margin-top:6px;gap:6px">${[['timing',tr('Chrono électrique','Electronic timing')],['wind',tr('Anémomètre','Wind gauge')],['doping',tr('Contrôle antidopage','Doping control')],['referee',tr('Rapport du juge-arbitre','Referee report')]].map(([k,l])=>`<button class="pill ${ck[k]?'ok':'warn hollow'}" ${can('records.ratify')?`onclick="recCheck('${r.id}','${k}')"`:''} style="cursor:${can('records.ratify')?'pointer':'default'}">${l}</button>`).join('')}</div></div>${can('records.ratify')?`<button class="btn pri sm" ${Object.values(ck).every(Boolean)?'':'disabled'} onclick="recRatify('${r.id}')">${ic('stamp')} ${tr('Homologuer','Ratify')}</button>`:''}</div>`}).join('')}</div></div>`:''}
  <div class="flat"><div class="mchip dark">${tr('Records du Sénégal','Senegalese records')}</div><div class="tblw"><table><thead><tr><th>${tr('Épreuve','Event')}</th><th>${tr('Hommes','Men')}</th><th class="hide-m"></th><th>${tr('Femmes','Women')}</th><th class="hide-m"></th></tr></thead><tbody>${EVENTS.filter(e=>NR[e.code]).map(e=>{const cell=s=>{const rat=DB.records.find(r=>r.status==='ratified'&&r.code===e.code&&r.sex===s);return rat?[`<span class="perf">${fmtPerf(e.code,rat.perf)}</span> <span class="tag nr">${tr('NOUVEAU','NEW')}</span>`,`${esc(fullName(P(rat.a)))} · ${D.y(rat.date)}`]:[`<span class="perf">${fmtPerf(e.code,e.ref[s])}</span>`,`${esc(NR[e.code][s][0])} · ${NR[e.code][s][1]}`]};const m=cell('M'),f=cell('F');return `<tr><td><b>${esc(tr(e.fr,e.en))}</b></td><td>${m[0]}<span class="l2 hide-m" style="display:none"></span></td><td class="hide-m muted">${m[1]}</td><td>${f[0]}</td><td class="hide-m muted">${f[1]}</td></tr>`}).join('')}</tbody></table></div></div><p class="xs muted" style="margin-top:10px">${tr('Records repris de la liste publique des records du Sénégal, à valider par la fédération avant mise en production. Tous les autres noms du prototype sont fictifs.','Records taken from the public list of Senegalese records, to be validated by the federation before go-live. Every other name in the prototype is fictional.')}</p>`}
 if(mode==='clubs'){const best={};DB.results.forEach(r=>{if(!legal(r)||COMP(r.compId)?.status!=='published')return;const k=r.a+r.code,pts=points(r.code,r.sex,r.perf);if(!best[k]||pts>best[k].pts)best[k]={pts,a:r.a}});const byClub={};Object.values(best).forEach(b=>{const cl=P(b.a)?.clubId;if(cl)(byClub[cl]=byClub[cl]||[]).push(b.pts)});const rows=Object.entries(byClub).map(([id,v])=>{v.sort((a,b)=>b-a);return {c:CLUB(id),pts:v.slice(0,15).reduce((a,b)=>a+b,0),n:v.length}}).filter(r=>!params.region||r.c.region===params.region).sort((a,b)=>b.pts-a.pts);
  body=`<div class="filters" style="margin-bottom:8px">${sel('region',REGIONS.map(r=>[r.code,r.name]),params.region,tr('Toutes les ligues','All leagues'))}<span class="sm muted">${tr('Somme des 15 meilleures performances du club (une par athlète et par épreuve), à l’indice.','Sum of the club’s 15 best marks (one per athlete and event), by index.')}</span></div><div class="flat"><div class="tblw"><table><thead><tr><th>${tr('Rang','Rank')}</th><th>Club</th><th class="hide-m">${tr('Ville - Ligue','City - League')}</th><th class="num hide-m">${tr('Perfs classantes','Scoring marks')}</th><th class="num">Points</th></tr></thead><tbody>${rows.slice(0,30).map((r,i)=>`<tr class="link" data-go="clubs/${r.c.id}"><td>${i<3?`<span class="rank r${i+1}">${i+1}</span>`:`<span class="tnum" style="padding-left:8px">${i+1}</span>`}</td><td><b>${esc(r.c.name)}</b></td><td class="hide-m">${esc(r.c.city)}<span class="l2">${r.c.region} - ${esc(regionName(r.c.region))}</span></td><td class="num hide-m">${r.n}</td><td class="num"><b class="tnum">${r.pts.toLocaleString('fr-FR')}</b></td></tr>`).join('')}</tbody></table></div></div>`}
 return `<div class="head"><div><h1>${tr('Bilans','Rankings')}</h1><div class="sub">${tr('Meilleures performances de la saison, par épreuve — seules les compétitions publiées et contrôlées comptent.','Season top lists by event — only published, checked competitions count.')}</div></div></div>
 <div class="seg" style="padding:4px;border-radius:12px;margin-bottom:14px">${[['',tr('Recherche par épreuve','By event')],['clubs',tr('Classement des clubs','Club standings')],['records',tr('Records & homologations','Records & ratification')]].map(([k,l])=>`<button style="height:36px;padding:0 16px;font-size:14px" class="${mode===k?'on':''}" onclick="go('rankings${k?'?mode='+k:''}')">${esc(l)}${k==='records'&&DB.records.some(r=>r.status==='pending')?` <span class="badge warn">${DB.records.filter(r=>r.status==='pending').length}</span>`:''}</button>`).join('')}</div>${body}`}
function recCheck(id,k){const r=DB.records.find(x=>x.id===id);r.checks[k]=!r.checks[k];save();render({keepScroll:true})}
function recRatify(id){const r=DB.records.find(x=>x.id===id);r.status='ratified';r.by=ME.id;log('Record national homologué','competitions',evName(r.code,r.sex)+' '+fmtPerf(r.code,r.perf));save();render({keepScroll:true});toast(tr('Record homologué','Record ratified'),'stamp')}

/* ============ clubs ============ */
const AFF={ok:['À jour','Up to date','ok',''],late:['En retard','Late','warn',''],pending:['En attente','Pending','info','hollow']};
function pageClubs(params){let list=myClubs();const q=(params.q||'').toLowerCase();if(q)list=list.filter(c=>(c.name+' '+c.city+' '+c.code).toLowerCase().includes(q));if(params.region)list=list.filter(c=>c.region===params.region);if(params.aff)list=list.filter(c=>params.aff==='late'?c.affiliation!=='ok':c.affiliation===params.aff);
 const cnt={};DB.people.forEach(p=>{const k=cnt[p.clubId]=cnt[p.clubId]||{n:0,ok:0};k.n++;if(['active','expiring'].includes(licStatus(p)))k.ok++});list=list.slice().sort((a,b)=>(cnt[b.id]?.n||0)-(cnt[a.id]?.n||0));
 return `<div class="head"><div><h1>${tr('Clubs affiliés','Affiliated clubs')}</h1><div class="sub">${list.length} ${tr('clubs','clubs')} · ${esc(scopeLabel(ME))}</div></div></div>
 <div class="filters" style="margin-bottom:10px"><input id="cl-q" placeholder="${tr('Nom, ville, code…','Name, city, code…')}" value="${esc(params.q||'')}" onchange="setParams({q:this.value,pg:''})">${ME.scope.kind==='all'?`<select aria-label="${tr('Ligue','League')}" onchange="setParams({region:this.value,pg:''})"><option value="">${tr('Toutes les ligues','All leagues')}</option>${REGIONS.map(r=>`<option value="${r.code}" ${params.region===r.code?'selected':''}>${esc(r.name)} (${DB.clubs.filter(c=>c.region===r.code).length})</option>`).join('')}</select>`:''}<select aria-label="Affiliation" onchange="setParams({aff:this.value,pg:''})"><option value="">${tr('Toutes affiliations','All affiliations')}</option><option value="ok" ${params.aff==='ok'?'selected':''}>${tr('À jour','Up to date')}</option><option value="late" ${params.aff==='late'?'selected':''}>${tr('À régulariser','To settle')}</option></select></div>
 <div class="flat"><div class="tblw"><table><thead><tr><th>Code</th><th>Club</th><th>${tr('Ville - Ligue','City - League')}</th><th class="num">${tr('Licenciés','Licensees')}</th><th class="num hide-m">${tr('En règle','In good standing')}</th><th class="hide-m">Affiliation ${DB.season.current}</th><th>${tr('Fiche','Sheet')}</th></tr></thead><tbody>${pageOf(list).map(c=>`<tr class="link" data-go="clubs/${c.id}"><td class="date mono">${c.code}</td><td><b>${esc(c.name)}</b></td><td>${esc(c.city)}<span class="l2">${c.region} - ${esc(regionName(c.region))}</span></td><td class="num">${cnt[c.id]?.n||0}</td><td class="num hide-m">${cnt[c.id]?.ok||0}</td><td class="hide-m">${pill(AFF,c.affiliation)}</td><td><a class="plus" href="#/clubs/${c.id}" aria-label="${tr('Ouvrir','Open')}">${ic('plus')}</a></td></tr>`).join('')}</tbody></table></div>${pager(list.length)}</div>`}
function pageClub(id){const c=CLUB(id);if(!c||!myClubs().includes(c))return notFound();const ppl=DB.people.filter(p=>p.clubId===id),ok=ppl.filter(p=>['active','expiring'].includes(licStatus(p))).length;const topA=ppl.map(p=>({p,pts:Math.max(0,...resultsOf(p.id).filter(legal).map(r=>points(r.code,r.sex,r.perf)))})).filter(x=>x.pts).sort((a,b)=>b.pts-a.pts).slice(0,6);
 return shellCrumbs([['Clubs','clubs'],[c.name]],`<div class="head"><div><span class="eyebrow mono">${c.code}</span><h1>${esc(c.name)}</h1><div class="sub">${esc(c.city)} · ${tr('Ligue de','League of')} ${esc(regionName(c.region))} · ${tr('fondé en','founded')} ${c.founded}</div></div><div class="actions">${pill(AFF,c.affiliation)}${c.affiliation!=='ok'&&can('clubs.manage')?`<button class="btn pri" onclick="clubPaid('${c.id}')">${ic('receipt')} ${tr('Enregistrer la cotisation','Record the fee')}</button>`:''}<a class="btn" href="#/licensees?club=${c.id}">${ic('contact')} ${tr('Voir les licenciés','View licensees')}</a></div></div>
 <div class="grid g4" style="margin-bottom:16px">${kpi(tr('Licenciés','Licensees'),ppl.length,'','users')}${kpi(tr('En règle','In good standing'),ok,'','badge-check')}${kpi(tr('Renouvelés','Renewed')+' '+DB.season.next,ppl.filter(renewed).length,'','refresh-cw','info')}${kpi(tr('Encadrants & officiels','Coaches & officials'),ppl.filter(p=>['encadrement','officiel'].includes(p.type)).length,'','graduation-cap','warn')}</div>
 <div class="grid g2"><div class="panel"><div class="hd"><h2>${tr('Fiche du club','Club sheet')}</h2></div><div class="bd"><dl class="dl">${[[tr('Président(e)','President'),c.president],[tr('Téléphone','Phone'),c.phone],['Email',c.email],[tr('Stade d’entraînement','Training venue'),c.venue],[tr('Cotisation d’affiliation','Affiliation fee'),c.affiliationPaid?tr('réglée le ','paid on ')+D.fmt(c.affiliationPaid):tr('non réglée','unpaid')],[tr('Femmes / hommes','Women / men'),`${ppl.filter(p=>p.sex==='F').length} / ${ppl.filter(p=>p.sex==='M').length}`]].map(([k,v])=>`<div><dt>${esc(k)}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl></div></div>
 <div class="panel"><div class="hd"><h2>${tr('Meilleurs athlètes 2026','Top athletes 2026')}</h2></div><div class="tblw"><table><tbody>${topA.map(({p,pts})=>`<tr class="link" data-go="licensees/${p.id}?tab=bilan"><td>${who(p,p.events.map(e=>evName(e,p.sex)).join(' · '))}</td><td class="num"><b class="tnum">${pts}</b> <span class="xs muted">pts · ${levelOf(pts)}</span></td></tr>`).join('')||`<tr><td>${empty(tr('Pas encore de résultats','No results yet'))}</td></tr>`}</tbody></table></div></div></div>`)}
function clubPaid(id){const c=CLUB(id);c.affiliation='ok';c.affiliationPaid=TODAY;log('Affiliation réglée','clubs',c.name);save();render({keepScroll:true});toast(tr('Affiliation à jour','Affiliation up to date'))}
